<script setup lang="ts">
import{ref,computed}from'vue';import{useEngine}from'../stores/engine';import{api}from'../services/api';import{confirmAction}from'../services/confirm';import{outputFor,outputLabel,speakerPayload,type Speaker}from'../types/engine';import Icon from'../components/Icon.vue';import Modal from'../components/Modal.vue';
const e=useEngine();const toneRequest=ref(false);const testSpeaker=ref<Speaker>();const testVolume=ref(25);const scanning=ref(false),summary=ref(''),error=ref(''),success=ref(''),editing=ref(false),existing=ref('');const form=ref({id:'',name:'',ip:'',model:'',enabled:true});const toneBusy=computed(()=>['connecting','playing','stopping'].includes(e.tone?.phase||''));const linked=(id:string)=>e.inputs.filter(input=>input.options?.speaker_id===id||e.routes.some(route=>route.input_ids.includes(input.id)&&route.speaker_ids.includes(id)));const testLabel=(id:string)=>e.tone?.speaker_id===id&&toneBusy.value?(e.tone.phase==='playing'?'停止测试音':e.tone.phase==='stopping'?'正在恢复…':'取消测试'):'播放测试音';
function deviceState(id:string){if(e.tone?.speaker_id===id&&toneBusy.value)return e.tone.phase==='playing'?'测试音播放中':e.tone.phase==='stopping'?'恢复入口中':'测试音连接中';return outputLabel(outputFor(e.snapshot,id))}
function edit(speaker?:Speaker){existing.value=speaker?.id||'';form.value={id:speaker?.id||'',name:speaker?.name||'',ip:speaker?.ip||'',model:speaker?.model||'',enabled:speaker?.enabled??true};error.value='';editing.value=true}
async function scan(){scanning.value=true;summary.value='';error.value='';try{const r=await e.run(()=>api('/discovery','POST'));const network=r.bind?` 已自动选择局域网 ${r.bind}。`:'';const restart=r.restart_required?' 当前 Engine 仍使用旧网卡，请在设置中重启后接收 AirPlay。':'';summary.value=(r.discovered?`搜索完成，发现 ${r.discovered} 台音箱，新增 ${r.added} 台，更新 ${r.updated??0} 台，已有 ${r.skipped} 台。`:'搜索完成，未发现音箱。请确认设备与 NAS 在同一局域网。')+network+restart}catch(err){error.value=String(err)}finally{scanning.value=false}}
async function save(){if(!await confirmAction('保存音箱设置','更改会重新加载音频服务，当前投放可能短暂中断。'))return;try{await e.run(()=>api('/engine/v1/speakers'+(existing.value?'/'+encodeURIComponent(existing.value):''),existing.value?'PATCH':'POST',speakerPayload(form.value,!!existing.value)));editing.value=false;success.value='音箱设置已保存'}catch(err){error.value=String(err)}}
async function remove(speaker:Speaker){if(!await confirmAction('删除音箱记录',`删除「${speaker.name}」的管理记录。再次搜索时仍可重新添加。`))return;try{await e.run(()=>api('/engine/v1/speakers/'+encodeURIComponent(speaker.id),'DELETE'));success.value='音箱记录已删除'}catch(err){error.value=String(err)}}
async function test(speaker:Speaker){if(e.tone?.speaker_id===speaker.id&&toneBusy.value){toneRequest.value=true;try{e.setTone(await api('/test-tone/stop','POST'));void e.refresh()}catch(err){error.value=String(err)}finally{toneRequest.value=false};return}testSpeaker.value=speaker;testVolume.value=outputFor(e.snapshot,speaker.id)?.volume_percent||25}
async function startTest(){const speaker=testSpeaker.value;if(!speaker)return;toneRequest.value=true;try{e.setTone(await api('/speakers/'+encodeURIComponent(speaker.id)+'/test-tone','POST',{volume_percent:testVolume.value}));testSpeaker.value=undefined;void e.refresh()}catch(err){error.value=String(err)}finally{toneRequest.value=false}}

</script>
<template><header class="page-header"><div><h1>妙播音箱</h1><p class="page-description">发现局域网设备，为每个空间找到自己的声音。</p></div><div class="actions"><button class="secondary" :disabled="e.busy||!e.snapshot?.engine_running||toneBusy" @click="edit()"><Icon name="plus" :size="18"/>手动添加</button><button :disabled="scanning||e.busy||!e.snapshot?.engine_running||toneBusy" :aria-busy="scanning" @click="scan"><Icon name="scan" :size="18" :scanning="scanning"/>{{scanning?'正在搜索…':'局域网发现'}}</button></div></header><p v-if="error||e.snapshot?.speakers_error" class="notice error" role="alert"><Icon name="warning"/><span>{{error||e.snapshot?.speakers_error}}</span></p><p v-if="e.tone?.phase==='failed'" class="notice error" role="alert"><Icon name="warning"/><span>测试音未完成：{{e.tone.error}}</span></p><p v-if="success" class="notice success" role="status"><Icon name="check"/><span>{{success}}</span></p><section v-if="scanning||summary" class="panel scan-status" role="status" aria-live="polite" :aria-busy="scanning"><div class="scan-copy"><Icon :name="scanning?'scan':'check'" :size="24"/><div><b>{{scanning?'正在搜索妙播音箱…':summary}}</b><p>{{scanning?'正在查找局域网设备并自动添加，请稍候。':'已有音箱的名称与关联保持不变，可在设备详情中编辑。'}}</p></div></div><progress v-if="scanning" aria-label="正在搜索妙播音箱"></progress></section><div v-if="!e.snapshot?.engine_running&&!toneBusy" class="section-note"><Icon name="info" :size="18"/><span>启动 Engine 后可以搜索音箱并管理设置。</span><RouterLink to="/settings">前往设置</RouterLink></div><section v-if="!e.speakers.length" class="panel empty-state"><span class="empty-icon"><Icon name="speaker" :size="36"/></span><h3>发现你的第一台音箱</h3><p>搜索到的设备会自动加入，之后可以改名或删除。</p><button :disabled="!e.snapshot?.engine_running||scanning" @click="scan"><Icon name="scan" :size="17"/>搜索妙播音箱</button></section><section v-if="e.speakers.length" class="panel speaker-list"><div class="panel-heading"><div><h2>你的音箱</h2><p>{{e.speakers.length}} 台设备 · 可在详情中重命名与管理</p></div></div><article v-for="speaker in e.speakers" :key="speaker.id" class="speaker-row"><span class="device-avatar"><Icon name="speaker" :size="25"/></span><div class="speaker-row-copy"><h3>{{speaker.name}}</h3><p>{{speaker.ip}}<span v-if="linked(speaker.id).length"> · 关联 {{linked(speaker.id).length}} 个接收器</span></p></div><span class="badge" :class="outputFor(e.snapshot,speaker.id)?.playback_state==='playing'?'blue':outputFor(e.snapshot,speaker.id)?.selected?'teal':'neutral'">{{deviceState(speaker.id)}}</span><div class="row-actions"><button class="secondary compact" :disabled="toneRequest||(!e.snapshot?.engine_running&&!toneBusy)||!speaker.enabled||(toneBusy&&e.tone?.speaker_id!==speaker.id)" @click="test(speaker)"><Icon :name="toneBusy&&e.tone?.speaker_id===speaker.id?'stop':'sound'" :size="16"/>{{testLabel(speaker.id)}}</button><button class="icon-button" :disabled="!e.snapshot?.engine_running||toneBusy" :aria-label="'编辑 '+speaker.name" @click="edit(speaker)"><Icon name="edit" :size="18"/></button></div></article></section><details class="help-details standalone"><summary><Icon name="info" :size="15"/>关于发现、音量和播放状态</summary><p>新增设备会重新加载当前音频服务；重复搜索保留用户命名与关联。播放状态来自 Engine 的 Sender 观测，未知不等于离线。独立实时音量尚未开放 Web API，请使用 AirPlay 或音箱按键。测试音只使用本地受控资源，不读取浏览器指定的服务器文件。</p></details><Modal :open="editing" :title="existing?'音箱详情':'添加音箱'" @close="editing=false"><form @submit.prevent="save"><label>名称<input v-model="form.name" required maxlength="80" placeholder="例如：客厅音箱"/></label><label>IPv4 地址<input v-model="form.ip" required pattern="(?:[0-9]{1,3}\.){3}[0-9]{1,3}" placeholder="192.168.1.100"/></label><label>型号（可选）<input v-model="form.model" placeholder="不限制预设型号"/></label><label class="toggle-row"><span><b>启用音箱</b><small>允许接收器使用这台设备</small></span><input type="checkbox" role="switch" v-model="form.enabled"/></label><div v-if="existing" class="detail-associations"><b>关联的接收器</b><p>{{linked(existing).map(i=>i.name).join('、')||'尚未关联'}}</p><RouterLink to="/inputs" @click="editing=false">管理接收器关联<Icon name="chevron" :size="14"/></RouterLink></div><p v-if="error" class="notice error">{{error}}</p><div class="dialog-actions spread"><button v-if="existing" type="button" class="text danger" :disabled="linked(existing).length>0||e.busy" :title="linked(existing).length?'先解除接收器关联才能删除':''" @click="async()=>{const speaker=e.speakers.find(s=>s.id===existing);if(speaker){await remove(speaker);editing=false}}"><Icon name="trash" :size="16"/>删除记录</button><div class="actions"><button type="button" class="secondary" @click="editing=false">取消</button><button :disabled="e.busy">保存</button></div></div></form></Modal><Modal :open="!!testSpeaker" title="播放测试音" @close="testSpeaker=undefined"><form @submit.prevent="startTest"><div class="test-target"><span class="device-avatar"><Icon name="speaker" :size="27"/></span><div><b>{{testSpeaker?.name}}</b><p>{{testSpeaker?.ip}}</p></div></div><label>测试音量<div class="volume-choice"><input type="range" min="1" max="100" step="1" v-model.number="testVolume" aria-label="测试音量"/><output>{{testVolume}}%</output></div></label><p class="field-help">所选音量会作用于音箱，停止后保留此设备音量；接收器配置不变。</p><div class="section-note"><Icon name="clock" :size="18"/><span>持续播放，由你手动停止；最长 5 分钟自动停止。</span></div><p class="field-help">请先取消所有 AirPlay 投放。测试会暂时重启接收器入口，结束后恢复；不混入当前音乐。</p><p v-if="error" class="notice error">{{error}}</p><div class="dialog-actions"><button type="button" class="secondary" :disabled="toneRequest" @click="testSpeaker=undefined">取消</button><button :disabled="toneRequest||toneBusy"><Icon name="play" :size="16"/>{{toneRequest?'准备中…':'开始播放'}}</button></div></form></Modal></template>
